head.b:skin:
/* ===== RESET & BASE STYLES ===== */
* { box-sizing: border-box; margin: 0; padding: 0; }
body {
  font-family: 'Be Vietnam Pro', -apple-system, sans-serif;
  background: radial-gradient(circle at 50% 0, #291e14, #0d0906);
  color: #e8dcc6;
  line-height: 1.6;
  min-height: 100vh;
}
a { color: #e5b36a; text-decoration: none; transition: all 0.2s ease; }
a:hover { color: #f1c40f; }

/* ===== NAVBAR ===== */
.kybien-navbar {
  background: linear-gradient(135deg, #8b0000, #4a0000);
  color: #ffffff;
  padding: 14px 20px;
  box-shadow: 0 4px 15px rgba(0, 0, 0, 0.5);
  position: relative;
  z-index: 10;
  border-bottom: 2px solid #f1c40f;
}
.nav-container {
  max-width: 1200px;
  margin: 0 auto;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
}
.brand-logo {
  font-size: 1.6rem;
  font-weight: 700;
  color: #fff;
  letter-spacing: 1px;
  display: flex;
  align-items: center;
  gap: 10px;
  font-family: 'Noto Serif TC', serif;
}
.brand-logo span { color: #f1c40f; }

.logo-general-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 38px;
  height: 38px;
  border-radius: 50%;
  background: #c62828;
  color: #ffffff;
  border: 2px solid #f1c40f;
  font-family: 'Noto Serif TC', serif;
  font-weight: 900;
  font-size: 1.15rem;
  box-shadow: 0 0 10px rgba(241,196,15,0.4);
}

.nav-links { display: flex; gap: 20px; list-style: none; align-items: center; }
.nav-links a { color: #ffffff; font-weight: 600; font-size: 0.95rem; }
.nav-links a:hover { color: #f1c40f; }

/* KHUNG ĐĂNG NHẬP HEADER */
.kybien-nav-auth {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}
.kybien-nav-auth input {
  background: #1e130a;
  border: 1px solid #5a3d22;
  color: #fff;
  padding: 6px 9px;
  border-radius: 6px;
  font-size: 0.8rem;
  outline: none;
  transition: border-color 0.2s;
}
.kybien-nav-auth input:focus {
  border-color: #f1c40f;
}
.kybien-nav-auth button {
  cursor: pointer;
  font-family: inherit;
}

/* ===== HERO SECTION (TRANG CHỦ) ===== */
.hero-section {
  background: linear-gradient(135deg, #33251a, #1a1009);
  border: 2px solid #5a3d22;
  border-radius: 16px;
  padding: 35px 25px;
  text-align: center;
  margin-bottom: 30px;
  box-shadow: 0 10px 30px rgba(0,0,0,0.5);
  position: relative;
}
.hero-badge {
  display: inline-block;
  background: #8b0000;
  color: #f1c40f;
  font-size: 0.82rem;
  font-weight: 700;
  padding: 4px 14px;
  border-radius: 20px;
  border: 1px solid #a83a1f;
  margin-bottom: 12px;
  text-transform: uppercase;
  letter-spacing: 1px;
}
.hero-title {
  font-family: 'Noto Serif TC', serif;
  font-size: 2.2rem;
  color: #f1c40f;
  margin-bottom: 10px;
  text-shadow: 0 2px 10px rgba(0,0,0,0.6);
}
.hero-subtitle {
  font-size: 1.05rem;
  color: #e8dcc6;
  max-width: 750px;
  margin: 0 auto 25px auto;
  line-height: 1.6;
}
.hero-actions {
  display: flex;
  justify-content: center;
  gap: 15px;
  flex-wrap: wrap;
}
.btn-hero-primary {
  background: linear-gradient(135deg, #8b0000, #500000);
  color: #ffffff !important;
  font-weight: 700;
  font-size: 1rem;
  padding: 12px 26px;
  border-radius: 10px;
  border: 1px solid #f1c40f;
  box-shadow: 0 4px 15px rgba(241,196,15,0.3);
  transition: transform 0.2s ease;
}
.btn-hero-primary:hover {
  transform: translateY(-2px);
  background: linear-gradient(135deg, #a83a1f, #8b0000);
}
.btn-hero-secondary {
  background: linear-gradient(135deg, #4a3320, #291e14);
  color: #f1c40f !important;
  font-weight: 700;
  font-size: 1rem;
  padding: 12px 26px;
  border-radius: 10px;
  border: 1px solid #5a3d22;
  transition: transform 0.2s ease;
}
.btn-hero-secondary:hover {
  transform: translateY(-2px);
  border-color: #f1c40f;
  color: #fff !important;
}

/* ===== 4 GAME VARIANT CARDS (TRANG CHỦ) ===== */
.variant-cards-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: 18px;
  margin-bottom: 35px;
}
.variant-card {
  background: linear-gradient(145deg, #271a10, #140b05);
  border: 1px solid #5a3d22;
  border-radius: 12px;
  padding: 20px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  transition: all 0.25s ease;
  box-shadow: 0 4px 14px rgba(0,0,0,0.3);
}
.variant-card:hover {
  transform: translateY(-4px);
  border-color: #f1c40f;
  box-shadow: 0 8px 20px rgba(241,196,15,0.25);
}
.variant-icon {
  font-size: 2.2rem;
  margin-bottom: 10px;
}
.variant-title {
  font-family: 'Noto Serif TC', serif;
  font-size: 1.25rem;
  color: #f1c40f;
  margin-bottom: 8px;
}
.variant-desc {
  font-size: 0.88rem;
  color: #a8947d;
  line-height: 1.5;
  margin-bottom: 16px;
}
.btn-play-variant {
  background: linear-gradient(135deg, #8b0000, #5a0000);
  color: #ffffff !important;
  font-weight: 700;
  font-size: 0.85rem;
  padding: 9px 14px;
  border-radius: 6px;
  text-align: center;
  border: 1px solid #a83a1f;
}
.btn-play-variant:hover {
  background: linear-gradient(135deg, #a83a1f, #8b0000);
  color: #f1c40f !important;
}

/* ===== THANH LỌC DANH MỤC (LABEL FILTER BAR) ===== */
.label-filter-bar {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
  margin-bottom: 25px;
  background: rgba(34, 21, 12, 0.6);
  padding: 12px 16px;
  border-radius: 10px;
  border: 1px solid #5a3d22;
}
.filter-btn {
  background: #33251a;
  color: #e8dcc6;
  padding: 6px 14px;
  border-radius: 20px;
  font-size: 0.85rem;
  font-weight: 600;
  border: 1px solid #5a3d22;
  transition: all 0.2s ease;
}
.filter-btn:hover, .filter-btn.active {
  background: #8b0000;
  color: #f1c40f;
  border-color: #f1c40f;
}

/* ===== MAIN LAYOUT ===== */
.main-wrapper {
  max-width: 1200px;
  margin: 20px auto 40px auto;
  padding: 0 15px;
}

.content-area {
  width: 100%;
}

/* SECTION HEADER TITLE */
.section-title-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 2px solid #5a3d22;
  padding-bottom: 10px;
  margin-bottom: 25px;
}
.section-title-bar h2 {
  font-family: 'Noto Serif TC', serif;
  font-size: 1.4rem;
  color: #f1c40f;
  letter-spacing: 1px;
}

/* GRID CÁC THẺ BÀI VIẾT BÌNH VĂN SA TRƯỜNG */
.post-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(330px, 1fr));
  gap: 22px;
}

.post-card {
  background: linear-gradient(145deg, #33251a, #20140b);
  border: 1px solid #5a3d22;
  border-radius: 12px;
  padding: 20px;
  box-shadow: 0 6px 18px rgba(0,0,0,0.4);
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  transition: transform 0.25s ease, border-color 0.25s ease;
}
.post-card:hover {
  transform: translateY(-4px);
  border-color: #f1c40f;
  box-shadow: 0 8px 25px rgba(241,196,15,0.2);
}
.post-card-tag {
  display: inline-block;
  background: #8b0000;
  color: #f1c40f;
  font-size: 0.75rem;
  font-weight: 700;
  padding: 3px 10px;
  border-radius: 4px;
  margin-bottom: 10px;
  text-transform: uppercase;
  letter-spacing: 1px;
}
.post-card-title {
  font-family: 'Noto Serif TC', serif;
  font-size: 1.25rem;
  font-weight: 700;
  color: #f1c40f;
  margin-bottom: 12px;
  line-height: 1.4;
}
.post-card-title a { color: #f1c40f; }
.post-card-title a:hover { color: #fff; }

.post-card-snippet {
  font-size: 0.9rem;
  color: #a8947d;
  line-height: 1.6;
  margin-bottom: 18px;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.btn-read-post {
  background: linear-gradient(135deg, #8b0000, #600000);
  color: #ffffff !important;
  font-weight: 700;
  font-size: 0.88rem;
  padding: 10px 18px;
  border-radius: 8px;
  text-align: center;
  display: block;
  border: 1px solid #a83a1f;
  box-shadow: 0 3px 10px rgba(139,0,0,0.4);
}
.btn-read-post:hover {
  background: linear-gradient(135deg, #a83a1f, #8b0000);
  color: #f1c40f !important;
  border-color: #f1c40f;
}

/* CHI TIẾT BÀI VIẾT & TRANG TĨNH SẢNH CỜ (STATIC / ITEM VIEW) */
.single-page-view {
  background: transparent;
  width: 100%;
}
.single-post-title {
  font-family: 'Noto Serif TC', serif;
  font-size: 2rem;
  font-weight: 700;
  color: #f1c40f;
  margin-bottom: 20px;
  text-align: center;
  line-height: 1.3;
}

/* STYLING BÌNH LUẬN SA TRƯỜNG */
.comments-section {
  margin-top: 45px;
  padding-top: 30px;
  border-top: 2px solid #5a3d22;
  background: linear-gradient(145deg, #22150c, #140b05);
  padding: 24px;
  border-radius: 12px;
  border: 1px solid #5a3d22;
}
.comments-title {
  font-family: 'Noto Serif TC', serif;
  color: #f1c40f;
  font-size: 1.4rem;
  margin-bottom: 20px;
}

/* STYLING PHÂN TRANG (PAGINATION) */
.blog-pager {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-top: 35px;
  padding-top: 20px;
  border-top: 1px solid #5a3d22;
}
.blog-pager-newer-link, .blog-pager-older-link, .home-link {
  background: linear-gradient(135deg, #4a3320, #291e14);
  color: #f1c40f !important;
  border: 1px solid #5a3d22;
  padding: 10px 18px;
  border-radius: 8px;
  font-weight: bold;
  font-size: 0.9rem;
  transition: all 0.2s ease;
}
.blog-pager-newer-link:hover, .blog-pager-older-link:hover, .home-link:hover {
  background: linear-gradient(135deg, #8b0000, #4a0000);
  color: #fff !important;
  border-color: #f1c40f;
}

/* FOOTER CHUYÊN NGHIỆP */
footer.kybien-footer {
  text-align: center;
  padding: 25px 20px;
  color: #a8947d;
  font-size: 0.9rem;
  border-top: 1px solid #33251a;
  margin-top: 50px;
  background: #120b06;
}

/* ===== RESPONSIVE MOBILE CHO BÀI VIẾT BLOG & BÀN CỜ (1 CỘT, KHÔNG CỐ ĐỊNH BÀN CỜ) ===== */
.kybien-post-layout {
  display: flex;
  flex-wrap: wrap;
  gap: 24px;
  align-items: flex-start;
}
.sticky-board-col {
  flex: 1 1 480px;
  max-width: 520px;
  order: 1;
  position: sticky;
  top: 20px;
  box-sizing: border-box;
}
.scrollable-story-col {
  flex: 1 1 420px;
  order: 2;
  box-sizing: border-box;
}

@media (max-width: 900px) {
  .nav-container {
    flex-direction: column;
    gap: 10px;
  }
  .nav-links {
    flex-wrap: wrap;
    justify-content: center;
    gap: 12px;
  }
  .main-wrapper {
    padding: 0 10px;
    margin: 15px auto 30px auto;
  }
  .single-post-title {
    font-size: 1.45rem;
    margin-bottom: 15px;
    line-height: 1.35;
  }
  /* 1 CỘT VÀ KHÔNG CỐ ĐỊNH BÀN CỜ TRÊN MOBILE */
  .kybien-post-layout {
    display: flex !important;
    flex-direction: column !important;
    gap: 18px !important;
  }
  .sticky-board-col {
    position: static !important;
    top: auto !important;
    width: 100% !important;
    max-width: 100% !important;
    flex: 1 1 auto !important;
    order: 1 !important;
    padding: 12px 8px !important;
    margin: 0 auto 10px auto !important;
    box-sizing: border-box !important;
  }
  .scrollable-story-col {
    width: 100% !important;
    max-width: 100% !important;
    flex: 1 1 auto !important;
    order: 2 !important;
    padding: 18px 14px !important;
    margin: 0 auto !important;
    box-sizing: border-box !important;
  }
  #chess-board-canvas {
    width: 100% !important;
    max-width: 100% !important;
    height: auto !important;
  }
  #kybien-replay-canvas {
    width: 100% !important;
    max-width: 440px !important;
    height: auto !important;
  }
  .sa-truong-article {
    font-size: 1.02rem !important;
    line-height: 1.8 !important;
  }
  .sa-truong-article .content {
    text-align: left !important;
  }
  .kybien-variant-header-badge {
    gap: 6px !important;
  }
  .kybien-variant-header-badge span {
    font-size: 0.8rem !important;
    padding: 5px 10px !important;
  }
  .kybien-post-summary-text {
    font-size: 0.95rem !important;
    padding: 10px 14px !important;
  }
  .viewer-controls {
    flex-wrap: wrap !important;
    gap: 6px !important;
  }
  .viewer-controls button {
    padding: 7px 12px !important;
    font-size: 0.82rem !important;
  }
}

footer.script:
//
    (function(){
      function renderStats(s){
        if(!s)return;
        var el=document.getElementById('online-stats-text');
        if(el){
          var t=s.total!=null?s.total:0,m=s.members!=null?s.members:0,g=s.guests!=null?s.guests:0;
          el.innerHTML='Tề tựu: <b>'+t+'</b> vị (<b>'+m+'</b> Kỳ thủ • <b>'+g+'</b> Lữ khách)';
        }
      }
      fetch('https://kybien-backend.onrender.com/api/stats/online')
        .then(function(r){return r.json();})
        .then(function(d){if(d&&d.data)renderStats(d.data);})
        .catch(function(){});
    })();
    //
